2	// and segment/path helpers. Both the Crow server and its clients import this
3	// package so they cannot drift on what a valid module path or response shape
4	// looks like.
5	package api
6	
7	type ModuleIdentifier struct {
8		Namespace string
9		Name      string
10		Provider  string
11	}
12	
13	type Module struct {
14		ModuleIdentifier
15		Version string
16	}
17	
18	type VersionEntry struct {
19		Version string `json:"version"`
20	}
21	
22	type ModuleVersions struct {
23		Versions []VersionEntry `json:"versions"`
24	}
25	
26	type ListVersionsResponse struct {
