	if !validAddress(address) {
		return fmt.Errorf("invalid module address %q", address)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("mkdir known-modules dir: %w", err)
	}

	existing, err := Load(path)
	if err != nil {
		return err
	}
	merged := mergeAndSort(existing, address)

	tmp, err := os.CreateTemp(filepath.Dir(path), ".known-modules-*.tmp")
	if err != nil {
		return fmt.Errorf("create temp: %w", err)
	}
	tmpName := tmp.Name()
	w := bufio.NewWriter(tmp)
	for _, addr := range merged {
		if _, err := w.WriteString(addr); err != nil {
			_ = tmp.Close()
			_ = os.Remove(tmpName)
			return fmt.Errorf("write temp: %w", err)
		}
		if err := w.WriteByte('\n'); err != nil {
			_ = tmp.Close()
			_ = os.Remove(tmpName)
			return fmt.Errorf("write temp: %w", err)
		}
	}
	if err := w.Flush(); err != nil {
		_ = tmp.Close()
		_ = os.Remove(tmpName)
		return fmt.Errorf("flush temp: %w", err)
	}
	if err := tmp.Close(); err != nil {
		_ = os.Remove(tmpName)
		return fmt.Errorf("close temp: %w", err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		_ = os.Remove(tmpName)
		return fmt.Errorf("rename temp: %w", err)
	}
	return nil
}

// mergeAndSort returns a deduplicated, sorted slice combining existing
// with the new address.
func mergeAndSort(existing []string, address string) []string {
	seen := make(map[string]struct{}, len(existing)+1)
	out := make([]string, 0, len(existing)+1)
	for _, a := range existing {
		if _, dup := seen[a]; dup {
			continue
		}
		seen[a] = struct{}{}
		out = append(out, a)
	}
	if _, dup := seen[address]; !dup {
		out = append(out, address)
	}
	sort.Strings(out)
	return out
}

// validAddress checks that s is exactly three slash-separated segments
// each passing api.ValidateSegments.
func validAddress(s string) bool {
	parts := strings.Split(s, "/")
	if len(parts) != 3 {
		return false
	}
	return api.ValidateSegments(parts) == nil
}
